package opsec

import (
	"encoding/json"
	"os"
	"sync"
	"time"
)

// IOC represents an Indicator of Compromise generated by tool execution.
type IOC struct {
	Timestamp time.Time `json:"timestamp"`
	Tool      string    `json:"tool"`
	Target    string    `json:"target"`
	Type      string    `json:"type"`
	Value     string    `json:"value"`
}

// Tracker records IOCs generated during operations for awareness/cleanup.
type Tracker struct {
	mu   sync.Mutex
	iocs []IOC
	file string
}

// NewTracker creates an IOC tracker that persists to the given file.
func NewTracker(file string) *Tracker {
	t := &Tracker{file: file}
	t.load()
	return t
}

// Record adds an IOC to the tracker.
func (t *Tracker) Record(tool, target, iocType, value string) {
	t.mu.Lock()
	defer t.mu.Unlock()

	t.iocs = append(t.iocs, IOC{
		Timestamp: time.Now(),
		Tool:      tool,
		Target:    target,
		Type:      iocType,
		Value:     value,
	})

	t.save()
}

// List returns all recorded IOCs.
func (t *Tracker) List() []IOC {
	t.mu.Lock()
	defer t.mu.Unlock()

	result := make([]IOC, len(t.iocs))
	copy(result, t.iocs)
	return result
}

// ListByTool returns IOCs filtered by tool name.
func (t *Tracker) ListByTool(tool string) []IOC {
	t.mu.Lock()
	defer t.mu.Unlock()

	var result []IOC
	for _, ioc := range t.iocs {
		if ioc.Tool == tool {
			result = append(result, ioc)
		}
	}
	return result
}

// Clear removes all tracked IOCs.
func (t *Tracker) Clear() {
	t.mu.Lock()
	defer t.mu.Unlock()

	t.iocs = nil
	t.save()
}

// Count returns the total number of tracked IOCs.
func (t *Tracker) Count() int {
	t.mu.Lock()
	defer t.mu.Unlock()
	return len(t.iocs)
}

func (t *Tracker) load() {
	if t.file == "" {
		return
	}
	data, err := os.ReadFile(t.file)
	if err != nil {
		return
	}
	_ = json.Unmarshal(data, &t.iocs)
}

func (t *Tracker) save() {
	if t.file == "" {
		return
	}
	data, _ := json.MarshalIndent(t.iocs, "", "  ")
	_ = os.WriteFile(t.file, data, 0600)
}
